import{Z as t,e as o,f as n,a0 as a}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Opayo","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/payments/opayo.md","filePath":"integrations/payments/opayo.md","lastUpdated":1782910942000}'),i={name:"integrations/payments/opayo.md"};function r(s,e,l,h,c,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="opayo" tabindex="-1">Opayo <a class="header-anchor" href="#opayo" aria-label="Permalink to &quot;Opayo&quot;">​</a></h1><p>Connect Opayo to take payments through the provider configured for your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Payments</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Opayo</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-opayo-api" tabindex="-1">Step 2. Connect to the Opayo API <a class="header-anchor" href="#step-2-connect-to-the-opayo-api" aria-label="Permalink to &quot;Step 2. Connect to the Opayo API&quot;">​</a></h3><ol><li>Go to the <a href="https://test.sagepay.com/mysagepay/settings.msp" target="_blank">Opayo Dashboard</a>.</li><li>Navigate to <strong>Settings</strong> → <strong>Administrator</strong>.</li><li>Click the <strong>Create API Credentials</strong> button.</li><li>Copy the <strong>Integration Key</strong> from Opayo and paste in the <strong>Integration Key</strong> field in Formie.</li><li>Copy the <strong>Integration Password</strong> from Opayo and paste in the <strong>Integration Password</strong> field in Formie.</li><li>Enter your <strong>Vendor Name</strong> in the <strong>Vendor Name</strong> field in Formie.</li></ol><h3 id="step-3-choose-a-checkout-mode" tabindex="-1">Step 3. Choose a Checkout Mode <a class="header-anchor" href="#step-3-choose-a-checkout-mode" aria-label="Permalink to &quot;Step 3. Choose a Checkout Mode&quot;">​</a></h3><ol><li>Select <strong>Checkout Mode</strong> for the integration: <ul><li><strong>Own Form</strong> — card fields are rendered on your page and tokenised client-side. This is the default.</li><li><strong>Drop-in Checkout</strong> — card fields are rendered inside an Opayo-hosted iframe on your page, which can reduce PCI scope compared to Own Form.</li></ul></li></ol><h3 id="step-4-test-connection" tabindex="-1">Step 4. Test Connection <a class="header-anchor" href="#step-4-test-connection" aria-label="Permalink to &quot;Step 4. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-5-field-setting" tabindex="-1">Step 5. Field Setting <a class="header-anchor" href="#step-5-field-setting" aria-label="Permalink to &quot;Step 5. Field Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Add a <strong>Payment</strong> field to your form.</li><li>Select Opayo for the <strong>Payment Provider</strong>.</li></ol><p>The Opayo payment integration supports only once-off payments.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Complete a test payment and inspect both the saved submission and the provider’s transaction record. Confirm the amount, currency and final payment state before enabling live payments.</p><p>If a 3D Secure callback cannot confirm payment, Formie leaves the payment pending. Check its transaction in Opayo before asking the visitor to pay again. An “operation not allowed” response can have more than one cause and does not by itself confirm a successful payment.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',17)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
